function validate([s, k]) {
  if (s.length < 1 || s.length > 100000) return 's needs 1 to 100,000 moves.';
  if (!/^[NSEW]+$/.test(s)) return "s may contain only 'N', 'S', 'E' and 'W'.";
  if (!Number.isInteger(k) || k < 0 || k > s.length) return 'k is between 0 and the length of s.';
  return null;
}

