function maxDistance(s, k) {
  let x = 0;
  let y = 0;
  let best = 0;

  for (let i = 0; i < s.length; i++) {
    if (s[i] === 'N') {
      y++;
    } else if (s[i] === 'S') {
      y--;
    } else if (s[i] === 'E') {
      x++;
    } else {
      x--;
    }
    const distance = Math.abs(x) + Math.abs(y);
    const reachable = Math.min(distance + 2 * k, i + 1);
    best = Math.max(best, reachable);
  }
  return best;
}

