function maxDistance(s, k) {
  // Follow every walk that rewrites at most k moves, one move at a time. For each point reached keep the most
  // rewrites left, since standing at the same point with more rewrites in hand can only reach more.
  const steps = new Map([['N', [0, 1]], ['S', [0, -1]], ['E', [1, 0]], ['W', [-1, 0]]]);
  const n = s.length, width = 2 * n + 1;
  let states = new Map([[n * width + n, k]]);
  let best = 0;
  for (const original of s) {
    const next = new Map();
    for (const [key, left] of states) {
      const x = Math.floor(key / width) - n, y = key % width - n;
      for (const [move, [dx, dy]] of steps) {
        const rest = move === original ? left : left - 1;
        if (rest < 0) continue;
        const nx = x + dx, ny = y + dy;
        best = Math.max(best, Math.abs(nx) + Math.abs(ny));
        const nkey = (nx + n) * width + (ny + n);
        if (!next.has(nkey) || next.get(nkey) < rest) next.set(nkey, rest);
      }
    }
    states = next;
  }
  return best;
}

