function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 8);
  // Uneven letter weights make some walks drift far and others keep doubling back.
  const weights = [rand(), rand(), rand(), rand()].map(w => w * w + 0.05);
  const total = weights.reduce((a, b) => a + b, 0);
  let s = '';
  for (let i = 0; i < n; i++) {
    let r = rand() * total, d = 0;
    while (d < 3 && r >= weights[d]) { r -= weights[d]; d++; }
    s += 'NSEW'[d];
  }
  // On long walks a small k is the interesting range, so favour it there; k = n is still possible.
  const k = Math.floor((size === 'large' ? rand() ** 3 : rand()) * (n + 1));
  return [s, Math.min(n, k)];
}
